#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto doOp=[&](int x,int y){
        assert(x>=1&&y>=1&&x+y<n);
        ops.push_back({x,y});
        // [prefix x | middle | suffix y] -> [suffix | middle | prefix]
        vector<int> res;
        for(int i=n-y;i<n;i++) res.push_back(p[i]);
        for(int i=x;i<n-y;i++) res.push_back(p[i]);
        for(int i=0;i<x;i++) res.push_back(p[i]);
        p=res;
    };

    auto findPos=[&](int val)->int{
        for(int i=0;i<n;i++) if(p[i]==val) return i;
        return -1;
    };

    for(int placed=0; placed<n-1; placed++){
        int pos=findPos(placed+1);
        if(pos==placed) continue;

        // Step 1: bring element to position n-1
        if(pos!=n-1){
            if(pos==0){
                // x=1, y=1 if n>2: brings p[n-1], p[1..n-2], p[0]. Target goes to n-1.
                if(n-1>1){ doOp(1,1); pos=n-1; }
            } else {
                // x=pos, y=n-1-pos: suffix=p[pos+1..n-1], mid=p[pos], prefix=p[0..pos-1]
                // Result: p[pos+1..n-1], p[pos], p[0..pos-1]. Target at position n-1-pos.
                // We want target at n-1. Use: x=pos+1, y=n-pos-1 if n-pos-1>=1 and pos+1>=1 and pos+1+n-pos-1<n => n<n. No!
                // x=pos, y=n-pos-1: need pos+n-pos-1<n => n-1<n. OK if pos>=1 and n-pos-1>=1 (pos<=n-2).
                // Result: p[pos+1..n-1], p[pos], p[0..pos-1]. target at index (n-1-pos-1)+1 = n-pos-1. Not n-1 unless pos=0.
                // Instead: move to pos 0 first. x=1,y=n-1-pos: suffix=p[pos+1..n-1], mid=p[1..pos], prefix=p[0].
                // target p[pos] is in mid at position (n-1-pos)+(pos-1)=n-2. Then from n-2 to n-1:
                // Simpler: use two ops. First bring to 0: x=pos, y=1 => [p[n-1], p[pos..n-2], p[0..pos-1]], target at pos in mid... 
                // Just bring to n-1: x=1, y=n-1-pos. Target at mid end = n-2. Then x=n-1,y=... no x+y<n.
                // x=n-2,y=1 => target from n-2 to n-1. 
                doOp(1, n-1-pos); pos=findPos(placed+1);
                if(pos!=n-1){ doOp(pos,1); pos=findPos(placed+1); }
                if(pos==placed) continue;
            }
        }
        // Step 2: bring from n-1 to placed
        if(pos==n-1 && placed<n-1){
            int y=n-1-placed; // y>=1
            int x=1; // x+y=n-placed, need <n => placed>0
            if(placed==0){ doOp(1,n-2); } 
            else { doOp(placed,n-1-placed); }
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
